  let left=healing?[-.11,-.10,-.22]:pistol?[-.052,-.10,.021]:[-.04,-.07,-.27*k];
  if(action==='reload'){const top=d.mag==='top',rocket=d.mag==='rocket',bull=d.mag==='bullpup';left=[-.045,-.07-out*.35,(bull?.23:-.06)*k+out*.07];if(top)left=[-.047,.16+out*.28,-.1];if(rocket)left=[-.065,.02-out*.1,-.47*k-out*.5];if(d.mag==='belt')left=[-.12,.10+out*.15,-.03];if(d.mag==='tube'||d.mag==='breech')left=[-.13*(1-t),-.08-out*.10,-.03];}
